const assert = require("assert");
const fs = require("fs");
const os = require("os");
const path = require("path");
const { ethers } = require("hardhat");
const taskFile = "../../hardhat/tasks/amm-xusd-wrbtc-delisting";
let task;
// Public chain runtime bytes retained to exercise the real runtime-hash guards.
const FIXTURE = JSON.parse(
    require("zlib")
        .inflateSync(
            Buffer.from(
                "",
                "base64"
            )
        )
        .toString()
);
const W = "0x924f5ad34698fd20c90fe5d5a8a0abd3b42dc711",
    C = "0x31a0f8400c75d52fdb413372233f28e3bdfb1c06",
    F = "0x2454ad964b04e343fa08e36f62a47113288917d0",
    A = "0xb2df96e24e20561b5ddda4c3599dacb6d773bae4",
    G = "0xa9c3d9681215ef7623dc28ea6b75bf87fdf285d9",
    GA = "0x6f96096687952349dd5944e0eb1be327dcdeb705",
    T = "0x967c84b731679e36a344002b8e3ce50620a7f69f",
    X = "0xb5999795be0ebb5bab23144aa5fd6a02d080299f",
    B = "0x542fda317318ebf1d3deaf76e0b632741a7e677d",
    OTHER = "0xefc78fc7d48b64958315949279ba181c2114abbd",
    CV2 = "0x1111111111111111111111111111111111111111",
    AN2 = "0x2222222222222222222222222222222222222222";
const ZERO = ethers.constants.AddressZero,
    BLOCK = "0x" + "cd".repeat(32),
    bn = ethers.BigNumber.from;
const DATA = "0x9e76a0070000000000000000000000002454ad964b04e343fa08e36f62a47113288917d0";
let dir;
function fixture() {
    const f = {
        chain: 30,
        owners: [...FIXTURE.owners],
        quorum: 3,
        codes: { ...FIXTURE.codes },
        entries: [{ anchor: A, converter: F, reserves: [X, B] }],
        metadataCalls: 0,
        sends: 0,
        signerCalls: 0,
        rows: [],
        walletReads: [],
        transactions: {},
        receipts: {},
        nonce: 7,
        white: [],
        logs: [],
    };
    f.file = path.join(dir, "journal.json");
    f.iface = new ethers.utils.Interface(task.MS_ABI);
    f.pending = ZERO;
    f.addStandard = (extra = {}) => {
        f.codes[CV2] = FIXTURE.codes[G];
        f.codes[AN2] = FIXTURE.codes[GA];
        f.entries.push({ anchor: AN2, converter: CV2, reserves: [X, B], ...extra });
    };
    const objects = {};
    const operation = (cv) => ({
        destination: C,
        value: bn(0),
        data: "0x9e76a007" + cv.slice(2).padStart(64, "0"),
        executed: false,
    });
    const wallet = {
        interface: f.iface,
        required: async () => bn(f.quorum),
        getOwners: async () => f.owners,
        isOwner: async (a) => f.owners.some((x) => x.toLowerCase() === a.toLowerCase()),
        transactionCount: async () => {
            throw new Error("Exchequer wallet history count is forbidden");
        },
        transactions: async (id) => {
            f.walletReads.push(String(id));
            return (
                f.rows[Number(id)] || {
                    destination: ZERO,
                    value: bn(0),
                    data: "0x",
                    executed: false,
                }
            );
        },
        getConfirmations: async () => [f.owners[0]],
        connect: () => ({
            estimateGas: { submitTransaction: async () => bn(100000) },
            submitTransaction: async (to, value, data, o) => {
                const j = JSON.parse(fs.readFileSync(f.file));
                const entry = j.operations.find((x) => x.operation.data === data);
                assert(entry && entry.intent, "Missing durable per-operation intent before send");
                assert.strictEqual(entry.intent.nonce, f.nonce);
                assert.strictEqual(o.gasLimit.toString(), "130000");
                assert.strictEqual(to, C);
                assert.strictEqual(value, 0);
                f.sends++;
                if (f.sendErrorAt === f.sends) throw Error("connection lost");
                const id = f.rows.length,
                    hash = "0x" + (id + 1).toString(16).padStart(64, "0");
                f.rows.push({ destination: to, value: bn(value), data, executed: false });
                const ev = f.iface.encodeEventLog(f.iface.getEvent("Submission"), [id]);
                f.receipts[hash] = {
                    status: 1,
                    transactionHash: hash,
                    blockNumber: 90,
                    blockHash: BLOCK,
                    logs: f.missingSubmission
                        ? []
                        : [
                              {
                                  address: W,
                                  topics: ev.topics,
                                  data: ev.data,
                                  transactionHash: hash,
                                  blockHash: BLOCK,
                              },
                              ...(f.unexpectedExecution
                                  ? [
                                        {
                                            address: W,
                                            ...f.iface.encodeEventLog(
                                                f.iface.getEvent("Execution"),
                                                [id]
                                            ),
                                            transactionHash: hash,
                                            blockHash: BLOCK,
                                        },
                                    ]
                                  : []),
                          ],
                };
                f.transactions[hash] = {
                    hash,
                    to: W,
                    from: f.owners[0],
                    nonce: f.nonce++,
                    value: bn(0),
                    data: f.iface.encodeFunctionData("submitTransaction", [to, value, data]),
                    blockNumber: 90,
                    blockHash: BLOCK,
                };
                if (f.lostReplyAt === f.sends) throw Error("lost broadcast reply");
                return { hash };
            },
        }),
    };
    objects[W] = wallet;
    objects[C] = {
        owner: async () => f.catalogueOwner || W,
        newOwner: async () => f.pending,
        registry: async () => task.PINS.mainRegistry.address,
        getAnchors: async () => f.entries.map((e) => e.anchor),
        getConvertibleTokenAnchors: async (t) =>
            f.entries.filter((e) => e.reserves.includes(t)).map((e) => e.anchor),
        isAnchor: async (a) => f.entries.some((e) => e.anchor === a),
        isLiquidityPool: async (a) => f.entries.some((e) => e.anchor === a),
        isConvertibleTokenAnchor: async (t, a) =>
            f.entries.some((e) => e.anchor === a && e.reserves.includes(t)),
    };
    objects[task.PINS.collector.address] = {
        getImplementation: async () => task.PINS.collectorImplementation.address,
        getWhitelistedConverterList: async () => f.white,
    };
    objects[task.PINS.data.address] = { registry: async () => task.PINS.mainRegistry.address };
    objects[task.PINS.network.address] = {
        registry: async () => task.PINS.mainRegistry.address,
        conversionPath: async (a, b) => (f.entries.length ? [a, f.entries[0].anchor, b] : []),
    };
    objects[task.PINS.mainRegistry.address] = {
        owner: async () => f.registryOwner || T,
        newOwner: async () => ZERO,
        addressOf: async (k) =>
            ({
                SovrynSwapConverterRegistry: C,
                SovrynSwapConverterRegistryData: task.PINS.data.address,
                SovrynSwapNetwork: task.PINS.network.address,
            })[ethers.utils.parseBytes32String(k)],
    };
    f.provider = {
        call: async () => {
            if (f.previewError) throw Error("removal preview reverted");
            return "0x";
        },
        getNetwork: async () => ({ chainId: f.chain }),
        getBlockNumber: async () => 100,
        getBlock: async () => ({ number: 100, hash: BLOCK }),
        getCode: async (a) => f.codes[a.toLowerCase()] || "0x",
        getTransactionCount: async () => f.nonce,
        getGasPrice: async () => bn(1),
        waitForTransaction: async (hash) => {
            if (f.timeout) throw Error("timeout");
            return f.receipts[hash];
        },
        getTransactionReceipt: async (hash) => f.receipts[hash],
        getTransaction: async (hash) => f.transactions[hash],
    };
    f.hre = {
        ethers: {
            ...ethers,
            Contract: function (address) {
                const a = address.toLowerCase();
                if (objects[a]) return objects[a];
                const e =
                    f.entries.find((e) => e.anchor === a || e.converter === a) ||
                    f.historical?.find((e) => e.anchor === a || e.converter === a);
                if (!e) return {};
                if (a === e.anchor) return { owner: async () => e.converter };
                return {
                    token: async () => {
                        f.metadataCalls++;
                        if (e.callback) throw Error("Callback getter reached");
                        return e.reportedAnchor || e.anchor;
                    },
                    connectorTokenCount: async () => bn(e.reserves.length),
                    connectorTokens: async (i) => e.reserves[i],
                };
            },
        },
        getNamedAccounts: async () => ({ deployer: f.owners[0] }),
    };
    f.hre.ethers.getSigner = async () => {
        f.signerCalls++;
        return { getAddress: async () => f.owners[0], provider: f.provider };
    };
    f.run = (args) =>
        task.runDelisting(
            { provider: f.provider, journal: f.file, log: (x) => f.logs.push(x), ...args },
            f.hre
        );
    f.op = operation;
    return f;
}
describe("XUSD/WRBTC catalogue delisting sweep", function () {
    before(() => {
        assert(
            fs.existsSync(path.join(__dirname, taskFile + ".js")),
            "Generic pair-scoped task is not implemented"
        );
        task = require(taskFile);
    });
    beforeEach(() => {
        dir = fs.mkdtempSync(path.join(fs.realpathSync(os.tmpdir()), "pair-delist-"));
    });
    afterEach(() => fs.rmSync(dir, { recursive: true, force: true }));
    it("previews the exact current fake call without requesting a signer or journal", async () => {
        const f = fixture(),
            r = await f.run({});
        assert.strictEqual(r.status, "dry-run");
        assert.strictEqual(r.candidates.length, 1);
        assert.strictEqual(r.candidates[0].operation.data, DATA);
        assert.strictEqual(f.signerCalls, 0);
        assert(!fs.existsSync(f.file));
    });
    it("discovers a new standard unselected pair converter and the current fake", async () => {
        const f = fixture();
        f.addStandard();
        const r = await f.run({});
        assert.strictEqual(r.candidates.length, 2);
        assert(r.candidates.every((c) => c.qualified));
    });
    it("includes the genuine converter when someone relists it", async () => {
        const f = fixture();
        f.entries.push({ anchor: GA, converter: G, reserves: [X, B] });
        const r = await f.run({});
        assert(r.candidates.some((c) => c.converter === G && c.qualified));
    });
    it("does not ignore extra-reserve entries associated with both tokens", async () => {
        const f = fixture();
        f.addStandard({ reserves: [X, B, OTHER] });
        const r = await f.run({});
        assert.strictEqual(r.candidates.find((c) => c.converter === CV2).reserves.length, 3);
    });
    it("ignores non-pair catalogue entries even if their code is unknown", async () => {
        const f = fixture();
        f.entries.push({ anchor: AN2, converter: CV2, reserves: [X, OTHER] });
        const r = await f.run({});
        assert.strictEqual(r.candidates.length, 1);
    });
    it("lists and proposes well-formed unknown code as UNQUALIFIED for later owner execution review", async () => {
        const f = fixture();
        f.addStandard();
        f.codes[CV2] = "0x6000";
        const r = await f.run({});
        const candidate = r.candidates.find((c) => c.converter === CV2);
        assert.strictEqual(candidate.qualified, false);
        assert.strictEqual(candidate.wellFormed, true);
        assert.strictEqual(candidate.preview, "0x");
        await f.run({ submit: true });
        assert.strictEqual(f.sends, 2);
        const record = JSON.parse(fs.readFileSync(f.file)).operations.find(
            (r) => r.candidate.converter === CV2
        );
        assert.strictEqual(record.candidate.qualified, false);
        assert(record.candidate.reviewRequired);
    });
    it("captures unknown anchor code as execution-review-required without a generic approval waiver", async () => {
        const f = fixture();
        f.addStandard();
        f.codes[AN2] = "0x6000";
        const r = await f.run({});
        const c = r.candidates.find((c) => c.converter === CV2);
        assert.strictEqual(c.qualified, false);
        assert.strictEqual(c.wellFormed, true);
    });
    it("blocks unreadable custom metadata/callback getters before signing", async () => {
        const f = fixture();
        f.addStandard({ callback: true });
        f.codes[CV2] = "0x6000";
        await assert.rejects(
            f.run({ submit: true }),
            /metadata|unreadable|well.formed|candidate/i
        );
        assert.strictEqual(f.sends, 0);
    });
    it("blocks a reverting actual from-wallet removal preview before signing", async () => {
        const f = fixture();
        f.previewError = true;
        await assert.rejects(f.run({ submit: true }), /metadata|preview|well.formed|candidate/i);
        assert.strictEqual(f.signerCalls, 0);
    });
    it("refuses metadata that would remove another anchor", async () => {
        const f = fixture();
        f.addStandard({ reportedAnchor: GA });
        const r = await f.run({});
        assert(!r.candidates.find((c) => c.converter === CV2).qualified);
        await assert.rejects(f.run({ submit: true }), /metadata|mismatch/i);
        assert.strictEqual(f.sends, 0);
    });
    it("submits multiple matches sequentially, with each mined proposal verified before the next", async () => {
        const f = fixture();
        f.addStandard();
        const r = await f.run({ submit: true });
        assert.strictEqual(f.sends, 2);
        assert.strictEqual(r.status, "submitted");
        const j = JSON.parse(fs.readFileSync(f.file));
        assert(j.operations.every((o) => o.status === "submitted" && o.proposalId !== undefined));
        assert.strictEqual(fs.statSync(f.file).mode & 0o777, 0o600);
    });
    it("stops after an ambiguous second send and never automatically resends on restart", async () => {
        const f = fixture();
        f.addStandard();
        f.sendErrorAt = 2;
        await assert.rejects(f.run({ submit: true }), /UNCERTAIN/);
        assert.strictEqual(f.sends, 2);
        await assert.rejects(f.run({ submit: true }), /UNCERTAIN/);
        assert.strictEqual(f.sends, 2);
    });
    it("reconciles a returned hash after a receipt timeout without resending", async () => {
        const f = fixture();
        f.timeout = true;
        await assert.rejects(f.run({ submit: true }), /timeout/);
        assert.strictEqual(f.sends, 1);
        f.timeout = false;
        await f.run({ submit: true });
        assert.strictEqual(f.sends, 1);
    });
    it("ignores an identical pending multisig transaction elsewhere without reading wallet history", async () => {
        const f = fixture();
        f.rows.push(f.op(F));
        const result = await f.run({ submit: true });
        assert.strictEqual(f.sends, 1);
        assert.strictEqual(result.operations[0].proposalId, "1");
        assert.deepStrictEqual(f.walletReads, ["1"]);
        assert.strictEqual(
            JSON.parse(fs.readFileSync(f.file)).operations[0].duplicateScan,
            undefined
        );
    });
    it("reads only its own new multisig transaction and journal ID when other wallet history exists", async () => {
        const f = fixture();
        f.rows = Array.from({ length: 12 }, () => f.op(G));
        await f.run({ submit: true });
        assert.deepStrictEqual(f.walletReads, ["12"]);
        f.walletReads = [];
        await f.run({ submit: true });
        assert(f.walletReads.length > 0);
        assert(f.walletReads.every((id) => id === "12"));
        assert.strictEqual(f.sends, 1);
    });
    it("never treats a successful outer receipt without Submission as a new proposal", async () => {
        const f = fixture();
        f.missingSubmission = true;
        await assert.rejects(f.run({ submit: true }), /Submission/);
        assert.strictEqual(f.sends, 1);
        assert(JSON.parse(fs.readFileSync(f.file)).operations[0].submissionHash);
    });
    it("is idempotent when the pair has no current entries", async () => {
        const f = fixture();
        f.entries = [];
        assert.strictEqual((await f.run({ submit: true })).status, "already-delisted");
        assert.strictEqual(f.sends, 0);
    });
    it("discovers public readmission in a later invocation rather than assuming a permanent ban", async () => {
        const f = fixture();
        f.entries = [];
        assert.strictEqual((await f.run({})).candidates.length, 0);
        f.addStandard();
        assert.strictEqual((await f.run({})).candidates[0].converter, CV2);
    });
    for (const [name, change, message] of [
        ["chain", (f) => (f.chain = 31), /chain ID30/],
        ["quorum", (f) => (f.quorum = 2), /owners\/quorum/],
        ["owners", (f) => (f.owners[0] = G), /owners\/quorum/],
        ["authority", (f) => (f.catalogueOwner = G), /authority drift/],
        ["pending owner", (f) => (f.pending = G), /authority drift/],
        ["catalogue runtime", (f) => (f.codes[C] = "0x6000"), /Unknown catalogue runtime/],
        ["registry owner", (f) => (f.registryOwner = G), /authority drift/],
        ["collector whitelist", (f) => (f.white = [G]), /containment drift/],
    ])
        it(`refuses ${name} drift before signing`, async () => {
            const f = fixture();
            change(f);
            await assert.rejects(f.run({ submit: true }), message);
            assert.strictEqual(f.signerCalls, 0);
            assert.strictEqual(f.sends, 0);
        });
    it("does not certify first-confirmation-only if the submission receipt contains Execution", async () => {
        const f = fixture();
        f.unexpectedExecution = true;
        await assert.rejects(f.run({ submit: true }), /Unexpected execution/);
        assert.strictEqual(f.sends, 1);
    });
    it("blocks candidate code changing during one pass", async () => {
        const f = fixture();
        f.addStandard();
        let calls = 0;
        const original = f.provider.getCode;
        f.provider.getCode = async (a) => (a === CV2 && ++calls > 1 ? "0x6001" : original(a));
        await assert.rejects(f.run({ submit: true }), /metadata|preview|candidate/i);
        assert.strictEqual(f.sends, 0);
    });

    it("reconciles a lost reply for the second operation without confusing the first stored hash", async () => {
        const f = fixture();
        f.addStandard();
        f.lostReplyAt = 2;
        await assert.rejects(f.run({ submit: true }), /UNCERTAIN/);
        const hash = "0x" + "2".padStart(64, "0");
        const r = await f.run({ submit: true, submissionHash: hash });
        assert.strictEqual(r.status, "submitted");
        assert.strictEqual(f.sends, 2);
        assert(JSON.parse(fs.readFileSync(f.file)).operations.every((o) => o.submissionHash));
    });
    async function executedFixture() {
        const f = fixture();
        await f.run({ submit: true });
        f.rows[0].executed = true;
        f.historical = [...f.entries];
        f.entries = [];
        const hash = "0x" + "ee".repeat(32);
        const event = (name) => ({
            address: W,
            ...f.iface.encodeEventLog(f.iface.getEvent(name), [0]),
            transactionHash: hash,
            blockHash: BLOCK,
        });
        f.receipts[hash] = {
            transactionHash: hash,
            status: 1,
            blockNumber: 90,
            blockHash: BLOCK,
            logs: [event("Execution")],
        };
        return { f, hash, event };
    }
    it("checks a stored pending operation without claiming execution", async () => {
        const f = fixture();
        await f.run({ submit: true });
        const result = await f.run({ checkTx: "0" });
        assert.strictEqual(result.status, "pending");
        assert.strictEqual(f.sends, 1);
    });
    it("does not treat executed storage alone as canonical inner execution proof", async () => {
        const { f } = await executedFixture();
        await assert.rejects(f.run({ checkTx: "0" }), /execution-hash/);
        assert.strictEqual(f.sends, 1);
    });
    it("checks canonical wallet Execution plus all removed-anchor associations", async () => {
        const { f, hash } = await executedFixture();
        const result = await f.run({ checkTx: hash });
        assert.strictEqual(result.status, "executed");
        assert.strictEqual(result.pairEntriesRemaining, 0);
        assert.strictEqual(f.sends, 1);
    });
    it("rejects an inner ExecutionFailure despite outer status1", async () => {
        const { f, hash, event } = await executedFixture();
        f.receipts[hash].logs = [event("ExecutionFailure")];
        await assert.rejects(f.run({ checkTx: "0", executionHash: hash }), /ExecutionFailure/);
    });
    it("rejects current relisting after an earlier successful execution", async () => {
        const { f, hash } = await executedFixture();
        f.entries = [...f.historical];
        await assert.rejects(f.run({ checkTx: "0", executionHash: hash }), /poststate/);
    });

    it("an existing submit lock preserves prior broadcast journal bytes before any reconciliation", async () => {
        const f = fixture();
        f.timeout = true;
        await assert.rejects(f.run({ submit: true }), /timeout/);
        f.timeout = false;
        const before = fs.readFileSync(f.file);
        const signerCalls = f.signerCalls;
        fs.writeFileSync(f.file + ".lock", "another writer", { mode: 0o600 });
        await assert.rejects(f.run({ submit: true }), /EEXIST/);
        assert.deepStrictEqual(fs.readFileSync(f.file), before);
        assert.strictEqual(f.signerCalls, signerCalls);
        assert.strictEqual(f.sends, 1);
        assert(fs.existsSync(f.file + ".lock"));
    });
    it("pins by explicit height when latest alias has a different header hash", async () => {
        const f = fixture();
        f.provider.getBlock = async (tag) => ({
            number: 100,
            hash: tag === "latest" ? "0x" + "ff".repeat(32) : BLOCK,
        });
        assert.strictEqual((await f.run({})).status, "dry-run");
    });
    it("journals the original and per-operation canonical metadata pins before submission", async () => {
        const f = fixture();
        await f.run({ submit: true });
        const journal = JSON.parse(fs.readFileSync(f.file));
        assert.strictEqual(journal.baseline.blockNumber, 100);
        assert.strictEqual(journal.baseline.blockHash, BLOCK);
        assert.strictEqual(journal.operations[0].preSendPin.blockHash, BLOCK);
    });
    it("prints every resumed multisig ID and final summary without another signer or send", async () => {
        const f = fixture();
        await f.run({ submit: true });
        const beforeSigner = f.signerCalls;
        f.logs = [];
        const result = await f.run({ submit: true });
        assert(
            f.logs.some(
                (line) => line.includes("EXCHEQUER PROPOSAL 0") && line.includes("resumed")
            )
        );
        assert.deepStrictEqual(result.summary, [
            {
                proposalId: "0",
                converter: F,
                submissionHash: "0x" + "1".padStart(64, "0"),
                origin: "resumed",
                status: "pending",
                executedFlag: false,
            },
        ]);
        assert(f.logs.some((line) => line.includes("EXCHEQUER PROPOSAL SUMMARY")));
        assert.strictEqual(f.signerCalls, beforeSigner);
        assert.strictEqual(f.sends, 1);
    });
    it("fills missing first verification time on resume and preserves an existing value", async () => {
        const f = fixture();
        await f.run({ submit: true });
        const journal = JSON.parse(fs.readFileSync(f.file));
        delete journal.operations[0].verifiedUTC;
        fs.writeFileSync(f.file, JSON.stringify(journal));
        await f.run({ submit: true });
        const verified = JSON.parse(fs.readFileSync(f.file)).operations[0].verifiedUTC;
        assert.strictEqual(typeof verified, "string");
        assert(verified.endsWith("Z"));
        await f.run({ submit: true });
        assert.strictEqual(
            JSON.parse(fs.readFileSync(f.file)).operations[0].verifiedUTC,
            verified
        );
        assert.strictEqual(f.sends, 1);
    });
});
